</head>
<body>
<main class="shell" id="app"></main>
<script type="module">
const app = document.querySelector('#app');
const escapeHtml = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function render() {
  const match = location.pathname.match(/^\/projects\/([^/]+)\/?$/);
  if (match) {
    let project;
    try { const response = await fetch('/api/projects/' + encodeURIComponent(decodeURIComponent(match[1]))); if (!response.ok) throw new Error(); project = await response.json(); }
    catch { app.innerHTML = '<h1>Project not found</h1><button class="back" type="button">Projects</button>'; app.querySelector('button').onclick = () => { location.href = '/'; }; return; }
    app.innerHTML = `<button class="back" type="button">Projects</button><h1>${escapeHtml(project.name)}</h1>`;
    app.querySelector('button').onclick = () => { location.href = '/'; };
    return;
  }
  const projects = await (await fetch('/api/projects')).json();
  app.innerHTML = `<h1>Workboard</h1><form class="form"><input aria-label="Project name" name="name" type="text"><button type="submit">Create project</button></form><div class="alert-slot" aria-live="polite"></div><section aria-label="Projects">${projects.map(p => `<div class="row" data-testid="project-row"><span class="row-name">${escapeHtml(p.name)}</span><button type="button" data-id="${escapeHtml(p.id)}">Open project</button></div>`).join('')}</section>`;
  app.querySelectorAll('[data-id]').forEach(button => button.addEventListener('click', () => { location.href = '/projects/' + encodeURIComponent(button.dataset.id); }));
  app.querySelector('form').addEventListener('submit', async event => {
    event.preventDefault();
    const name = new FormData(event.currentTarget).get('name').trim();
    if (!name) { app.querySelector('.alert-slot').innerHTML = '<p role="alert">Project name is required</p>'; return; }
    const response = await fetch('/api/projects', { method: 'POST', headers: {'content-type':'application/json'}, body: JSON.stringify({name}) });
    if (response.ok) render();
  });
}
render();
</script>
</body>
